#include <bits/stdc++.h>
using namespace std;
#define ll long long
const int maxn = 505;
int n, m, mod;
int C[maxn][maxn];
int f[maxn], g[maxn];
int F[maxn][maxn], G[maxn][maxn];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m >> mod;
    for (int i = 0; i <= n; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % mod;
        }
    }
    f[0] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= i; ++j) {
            int temp1 = (long long)f[j - 1] * f[i - j] % mod;
            temp1 = (long long)temp1 * (i + 1) % mod;
            temp1 = (long long)temp1 * C[i - 1][j - 1] % mod;
            f[i] = (f[i] + temp1) % mod;

            int temp2 = (long long)f[j - 1] * g[i - j] % mod;
            temp2 = (long long)temp2 * (i + 1) % mod;
            temp2 = (long long)temp2 * C[i - 1][j - 1] % mod;
            g[i] = (g[i] + temp2) % mod;

            int temp3 = (long long)g[j - 1] * f[i - j] % mod;
            temp3 = (long long)temp3 * (i + 1) % mod;
            temp3 = (long long)temp3 * C[i - 1][j - 1] % mod;
            g[i] = (g[i] + temp3) % mod;

            int sumC = (C[j][2] + C[i - j + 1][2]) % mod;
            int temp4 = (long long)f[j - 1] * f[i - j] % mod;
            temp4 = (long long)temp4 * sumC % mod;
            temp4 = (long long)temp4 * C[i - 1][j - 1] % mod;
            g[i] = (g[i] + temp4) % mod;
        }
    }
    F[0][0] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= min(i, m); ++j) {
            for (int l = 0; l < j; ++l) {
                int tempF = (long long)f[l] * F[i - l - 1][j - l] % mod;
                tempF = (long long)tempF * C[j][l] % mod;
                F[i][j] = (F[i][j] + tempF) % mod;

                int tempG1 = (long long)g[l] * F[i - l - 1][j - l] % mod;
                tempG1 = (long long)tempG1 * C[j][l] % mod;
                G[i][j] = (G[i][j] + tempG1) % mod;

                int tempG2 = (long long)f[l] * G[i - l - 1][j - l] % mod;
                tempG2 = (long long)tempG2 * C[j][l] % mod;
                G[i][j] = (G[i][j] + tempG2) % mod;
            }
            F[i][j] = (F[i][j] + f[j]) % mod;
            G[i][j] = (G[i][j] + g[j]) % mod;
        }
    }
    cout << G[n][m] << "\n";
    return 0;
}
